import{_ as a,c as t,o as e,a1 as o}from"./chunks/framework.7AAjiCkA.js";const m=JSON.parse('{"title":"活动福利、系统赠送额度","description":"","frontmatter":{},"headers":[],"relativePath":"other/活动福利.md","filePath":"other/活动福利.md"}'),l={name:"other/活动福利.md"},c=o('<h1 id="活动福利、系统赠送额度" tabindex="-1">活动福利、系统赠送额度 <a class="header-anchor" href="#活动福利、系统赠送额度" aria-label="Permalink to &quot;活动福利、系统赠送额度&quot;">​</a></h1><h3 id="活动福利" tabindex="-1">活动福利 <a class="header-anchor" href="#活动福利" aria-label="Permalink to &quot;活动福利&quot;">​</a></h3><h4 id="x-chat将在各社媒平台、官网等通过活动不定期发放额度奖励。" tabindex="-1">X-Chat将在各社媒平台、官网等通过活动不定期发放额度奖励。 <a class="header-anchor" href="#x-chat将在各社媒平台、官网等通过活动不定期发放额度奖励。" aria-label="Permalink to &quot;X-Chat将在各社媒平台、官网等通过活动不定期发放额度奖励。&quot;">​</a></h4><p>额度发放方式：</p><ul><li>邮件发放额度兑换码</li><li>系统直充</li><li>官网发放额度兑换码</li></ul><div class="tip custom-block"><p class="custom-block-title">系统直充说明</p><p>系统直充将直接充值到 <code>X-Chat用户API授权中心</code> 用户个人账户，无需用户手动兑换。常见于周年庆、法定节假日等场景。</p></div><div class="tip custom-block"><p class="custom-block-title">官网发放额度兑换码说明</p><p>用户可在导航栏-用户中心-Token信息查询中查看。如系统发放该奖励，则将会在该处显示一个兑换码。此兑换码可以前往导航栏-Token后台（ <code>X-Chat用户API授权中心</code> ）中兑换。</p></div><h3 id="邀请奖励" tabindex="-1">邀请奖励 <a class="header-anchor" href="#邀请奖励" aria-label="Permalink to &quot;邀请奖励&quot;">​</a></h3><ul><li>每个用户在注册X-Chat时系统都会为其生成一个专属的6位数 <code>邀请码</code> ，用户在注册的时候可以输入来自其他用户的邀请码（也可之后可以在用户中心-邀请明细中填写）。</li><li>在用户中心-邀请明细中可以查看邀请其他用户的数量，邀请数量多的用户每月可以获得额外的Token奖励。具体请联系客服。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>每个用户只可以填写一次邀请码。填写邀请码双方均会获得额度奖励，这个奖励也只有一次。</p></div><ul><li>通过邀请他人注册获得的邀请奖励将由系统直充到个人账户中，不会提醒。</li></ul>',11),i=[c];function s(r,d,h,n,_,p){return e(),t("div",null,i)}const k=a(l,[["render",s]]);export{m as __pageData,k as default};
